      shippingCalculator: new FlatShippingCalculator(500, 6000),
    });
    cart.add(mkProduct("a", 10000), 1);
    // subtotal 10000, discount 5000, discounted 5000 < freeOver 6000 → 500 shipping
    const t = cart.totals();
    expect(t.shippingCents).toBe(500);
