  });

  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);

    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher: fetcher });
    expect(result.totals.subtotalCents).toBe(1500);
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("a");
  });

  it("throws InventoryError when available is false", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 5);

    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: false, reason: "discontinued" }),
    };
    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.unreachable("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const ie = e as InventoryError;
      expect(ie.productId).toBe("a");
      expect(ie.requested).toBe(5);
    }
  });

  it("throws InventoryError on partial-stock denial (availableQuantity < requested)", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 10);

    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.unreachable("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const ie = e as InventoryError;
      expect(ie.productId).toBe("a");
      expect(ie.requested).toBe(10);
      expect(ie.available).toBe(3);
    }
  });

  it("passes when inventory check is available with sufficient quantity", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);

    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 5,
      }),
    };
    const result = await cart.checkout({ inventoryChecker: checker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("uses asyncTaxProvider for tax calculation", async () => {
    const cart = new Cart({
      discountPolicy: new NoDiscountPolicy(),
      region: "US-CA",
    });
    cart.add(mkProduct("a", 10000), 1);

    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };
    const result = await cart.checkout({ asyncTaxProvider: provider });
    // tax = floor(10000 * 0.0875) = 875
    expect(result.totals.taxCents).toBe(875);
    expect(provider.getRate).toHaveBeenCalledWith("US-CA");
  });

  it("async tax works with discount + shipping composition", async () => {
    const cart = new Cart({
      discountPolicy: new FixedAmountDiscountPolicy(1000),
      shippingCalculator: new FlatShippingCalculator(500),
      region: "US",
    });
    cart.add(mkProduct("a", 10000), 1);

    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.10),
    };
    const result = await cart.checkout({ asyncTaxProvider: provider });
    // subtotal 10000, discount 1000, discounted 9000
    // tax = floor(9000 * 0.10) = 900
    // shipping 500
    expect(result.totals.discountCents).toBe(1000);
    expect(result.totals.taxCents).toBe(900);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(9000 + 900 + 500);
  });

  it("propagates asyncTaxProvider error", async () => {
    const cart = new Cart({ region: "US" });
    cart.add(mkProduct("a", 1000), 1);

    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider: provider })).rejects.toThrow(
      "tax service down",
    );
  });

  it("uses all collaborators together", async () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      shippingCalculator: new FlatShippingCalculator(300),
      region: "FR",
    });
    cart.add(mkProduct("a", 5000), 2);

    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(6000),
    };
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const taxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.20),
    };

    const result = await cart.checkout({
      priceFetcher: fetcher,
      inventoryChecker: checker,
      asyncTaxProvider: taxProvider,
    });

    // refreshed price: 6000 × 2 = 12000 subtotal
    // discount 10% of 12000 = 1200, discounted = 10800
    // tax 20% of 10800 = 2160
    // shipping 300
    expect(result.totals.subtotalCents).toBe(12000);
    expect(result.totals.discountCents).toBe(1200);
    expect(result.totals.taxCents).toBe(2160);
    expect(result.totals.shippingCents).toBe(300);
    expect(result.totals.totalCents).toBe(10800 + 2160 + 300);
  });

  it("inventory check uses first denial among multiple lines", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    cart.add(mkProduct("b", 2000), 5);

    const checker: InventoryChecker = {
      check: vi.fn()
        .mockResolvedValueOnce({ available: true })
        .mockResolvedValueOnce({ available: false, reason: "out of stock" }),
    };

    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.unreachable("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      expect((e as InventoryError).productId).toBe("b");
    }
  });

  it("checkout without any collaborators uses sync pipeline", async () => {
    const cart = new Cart({
      taxCalculator: new RegionalTaxCalculator({ US: 0.05 }),
      region: "US",
    });
    cart.add(mkProduct("a", 2000), 1);
    const result = await cart.checkout();
    expect(result.totals.taxCents).toBe(100);
    expect(result.totals.totalCents).toBe(2100);
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it("returns 0 for a positive subtotal", () => {
    expect(policy.computeDiscountCents(10000)).toBe(0);
  });

  it("returns 0 for zero subtotal", () => {
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    expect(policy.computeDiscountCents(-500)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  it("rejects negative percent", () => {
    expect(() => new PercentageDiscountPolicy(-1)).toThrow(RangeError);
  });

  it("rejects percent > 100", () => {
    expect(() => new PercentageDiscountPolicy(101)).toThrow(RangeError);
  });

  it("rejects NaN", () => {
    expect(() => new PercentageDiscountPolicy(NaN)).toThrow(RangeError);
  });

  it("rejects Infinity", () => {
    expect(() => new PercentageDiscountPolicy(Infinity)).toThrow(RangeError);
  });

  it("accepts 0%", () => {
    const p = new PercentageDiscountPolicy(0);
    expect(p.computeDiscountCents(10000)).toBe(0);
  });

  it("accepts 100%", () => {
    const p = new PercentageDiscountPolicy(100);
    expect(p.computeDiscountCents(10000)).toBe(10000);
  });

  it("computes 10% of 10000 = 1000", () => {
    const p = new PercentageDiscountPolicy(10);
    expect(p.computeDiscountCents(10000)).toBe(1000);
  });

  it("rounds down fractional cents", () => {
    const p = new PercentageDiscountPolicy(33);
    // 33% of 100 = 33.0 → 33
    expect(p.computeDiscountCents(100)).toBe(33);
    // 33% of 101 = 33.33 → 33
    expect(p.computeDiscountCents(101)).toBe(33);
  });

  it("returns 0 for zero subtotal", () => {
    const p = new PercentageDiscountPolicy(50);
    expect(p.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const p = new PercentageDiscountPolicy(50);
    expect(p.computeDiscountCents(-1000)).toBe(0);
  });

  it("handles very large subtotals", () => {
    const p = new PercentageDiscountPolicy(15);
    expect(p.computeDiscountCents(99999999)).toBe(Math.floor(99999999 * 15 / 100));
  });
});

describe("FixedAmountDiscountPolicy", () => {
  it("rejects negative amount", () => {
    expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
  });

  it("rejects non-integer amount", () => {
    expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
  });

  it("accepts zero amount", () => {
    const p = new FixedAmountDiscountPolicy(0);
    expect(p.computeDiscountCents(5000)).toBe(0);
  });

  it("returns full amount when subtotal exceeds it", () => {
    const p = new FixedAmountDiscountPolicy(500);
    expect(p.computeDiscountCents(10000)).toBe(500);
  });

  it("caps at subtotal when amount exceeds subtotal", () => {
    const p = new FixedAmountDiscountPolicy(5000);
    expect(p.computeDiscountCents(2000)).toBe(2000);
  });

  it("returns 0 for zero subtotal", () => {
    const p = new FixedAmountDiscountPolicy(500);
    expect(p.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const p = new FixedAmountDiscountPolicy(500);
    expect(p.computeDiscountCents(-100)).toBe(0);
  });
});

describe("CompositeDiscountPolicy", () => {
  it("rejects empty policy list", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow(
      "CompositeDiscountPolicy requires at least one policy",
    );
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 10000 = 1000; fixed 200 → total 1200
      expect(composite.computeDiscountCents(10000)).toBe(1200);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-500)).toBe(0);
    });

    it("defaults to sum mode when not specified", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(composite.computeDiscountCents(10000)).toBe(1200);
    });

    it("can exceed subtotal (caller clamps)", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(600), new FixedAmountDiscountPolicy(600)],
        "sum",
      );
      // Each child caps at 1000, so 1000 + 1000 = 2000 (exceeds subtotal)
      expect(composite.computeDiscountCents(1000)).toBe(2000);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // 10% of 10000 = 1000, remaining 9000; 10% of 9000 = 900; total = 1900
      expect(composite.computeDiscountCents(10000)).toBe(1900);
    });

    it("order matters in chain mode", () => {
      const compositeA = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // fixed 500 from 10000 → remaining 9500; 10% of 9500 = 950; total = 1450
      expect(compositeA.computeDiscountCents(10000)).toBe(1450);

      const compositeB = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(500)],
        "chain",
      );
      // 10% of 10000 = 1000 → remaining 9000; fixed 500; total = 1500
      expect(compositeB.computeDiscountCents(10000)).toBe(1500);
    });

    it("stops compounding when remaining is 0", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(10000), new PercentageDiscountPolicy(50)],
        "chain",
      );
      // fixed takes all 5000; remaining 0; 50% of 0 = 0; total = 5000
      expect(composite.computeDiscountCents(5000)).toBe(5000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

