      expect(compositeB.computeDiscountCents(10000)).toBe(1500);
    });

    it("stops compounding when remaining is 0", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(10000), new PercentageDiscountPolicy(50)],
        "chain",
      );
      // fixed takes all 5000; remaining 0; 50% of 0 = 0; total = 5000
      expect(composite.computeDiscountCents(5000)).toBe(5000);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
