      discountPolicy: new NoDiscountPolicy(),
      region: "US-CA",
    });
    cart.add(mkProduct("a", 10000), 1);

    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };
