      discountPolicy: new FixedAmountDiscountPolicy(1000),
      shippingCalculator: new FlatShippingCalculator(500),
      region: "US",
    });
    cart.add(mkProduct("a", 10000), 1);

    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.10),
    };
    const result = await cart.checkout({ asyncTaxProvider: provider });
