import { describe, it, expect, vi } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine } from "../src/product.ts";

describe("NoTaxCalculator", () => {
  const calc = new NoTaxCalculator();

  it("returns 0 regardless of inputs", () => {
    expect(calc.computeTaxCents(10000, "US")).toBe(0);
    expect(calc.computeTaxCents(0, "FR")).toBe(0);
    expect(calc.computeTaxCents(-500, "GB")).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  it("rejects default rate < 0", () => {
    expect(() => new RegionalTaxCalculator({}, -0.01)).toThrow(RangeError);
  });

  it("rejects default rate > 1", () => {
    expect(() => new RegionalTaxCalculator({}, 1.01)).toThrow(RangeError);
  });

  it("rejects NaN default rate", () => {
    expect(() => new RegionalTaxCalculator({}, NaN)).toThrow(RangeError);
  });

  it("rejects region rate out of range", () => {
    expect(() => new RegionalTaxCalculator({ US: 1.5 })).toThrow(RangeError);
    expect(() => new RegionalTaxCalculator({ US: -0.1 })).toThrow(RangeError);
  });

  it("rejects NaN region rate", () => {
    expect(() => new RegionalTaxCalculator({ US: NaN })).toThrow(RangeError);
  });

  it("looks up region rate and rounds down", () => {
    const calc = new RegionalTaxCalculator({ "US-CA": 0.0875 });
    // 0.0875 * 10000 = 875
    expect(calc.computeTaxCents(10000, "US-CA")).toBe(875);
    // 0.0875 * 9999 = 874.9125 → 874
    expect(calc.computeTaxCents(9999, "US-CA")).toBe(874);
  });

  it("falls back to default rate for unknown region", () => {
    const calc = new RegionalTaxCalculator({ FR: 0.20 }, 0.10);
    expect(calc.computeTaxCents(10000, "GB")).toBe(1000);
  });

  it("falls back to 0 when no default and unknown region", () => {
    const calc = new RegionalTaxCalculator({ FR: 0.20 });
    expect(calc.computeTaxCents(10000, "GB")).toBe(0);
  });

  it("returns 0 for zero taxable", () => {
    const calc = new RegionalTaxCalculator({ US: 0.10 });
    expect(calc.computeTaxCents(0, "US")).toBe(0);
  });

  it("returns 0 for negative taxable", () => {
    const calc = new RegionalTaxCalculator({ US: 0.10 });
    expect(calc.computeTaxCents(-1000, "US")).toBe(0);
  });

  it("accepts boundary rates 0 and 1", () => {
    const calc0 = new RegionalTaxCalculator({ US: 0 });
    expect(calc0.computeTaxCents(5000, "US")).toBe(0);

    const calc1 = new RegionalTaxCalculator({ US: 1 });
    expect(calc1.computeTaxCents(5000, "US")).toBe(5000);
  });
});

describe("AsyncTaxCalculator", () => {
  it("returns 0 for zero taxable without calling provider", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.10),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(0, "US")).toBe(0);
    expect(provider.getRate).not.toHaveBeenCalled();
  });

  it("returns 0 for negative taxable without calling provider", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.10),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(-100, "US")).toBe(0);
    expect(provider.getRate).not.toHaveBeenCalled();
  });

  it("computes tax from async rate and rounds down", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };
    const calc = new AsyncTaxCalculator(provider);
    // 0.0875 * 9999 = 874.9125 → 874
    expect(await calc.computeTaxCents(9999, "US-CA")).toBe(874);
    expect(provider.getRate).toHaveBeenCalledWith("US-CA");
  });

  it("throws RangeError for rate > 1", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(1.5),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError for negative rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(-0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError for NaN rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(NaN),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("propagates provider rejection", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("network down")),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow("network down");
  });
});

describe("totalLineWeightGrams", () => {
  it("returns 0 for empty lines", () => {
    expect(totalLineWeightGrams([])).toBe(0);
  });

  it("sums weight × quantity", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100, weightGrams: 200 }, quantity: 3 },
      { product: { id: "b", name: "B", unitPriceCents: 100, weightGrams: 500 }, quantity: 2 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(200 * 3 + 500 * 2);
  });

  it("treats undefined weightGrams as 0", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 5 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(0);
  });
});

