import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { PercentageDiscountPolicy, FixedAmountDiscountPolicy, NoDiscountPolicy } from "../src/pricing.ts";
import { RegionalTaxCalculator, NoTaxCalculator, type AsyncTaxRateProvider } from "../src/tax.ts";
import { FlatShippingCalculator, FreeShippingCalculator } from "../src/shipping.ts";
import { InventoryError, type PriceFetcher, type InventoryChecker } from "../src/inventory.ts";
import type { Product } from "../src/product.ts";

const mkProduct = (id: string, priceCents: number, weightGrams?: number): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents: priceCents,
  weightGrams,
});

describe("Cart line management", () => {
  it("add() stores a product", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
    expect(cart.itemCount).toBe(2);
  });

  it("add() merges quantities for same product id", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
    cart.add(mkProduct("a", 1000), 3);
    expect(cart.itemCount).toBe(5);
  });

  it("add() rejects non-positive quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(mkProduct("a", 1000), 0)).toThrow(RangeError);
    expect(() => cart.add(mkProduct("a", 1000), -1)).toThrow(RangeError);
  });

  it("add() rejects non-integer quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(mkProduct("a", 1000), 1.5)).toThrow(RangeError);
  });

  it("add() rejects negative unitPriceCents", () => {
    const cart = new Cart();
    expect(() => cart.add(mkProduct("a", -1), 1)).toThrow(RangeError);
  });

  it("remove() deletes a product and returns true", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove() returns false for unknown id", () => {
    const cart = new Cart();
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity() changes quantity", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity(0) removes the line", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity() rejects negative quantity", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity() rejects non-integer quantity", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
  });

  it("updateQuantity() throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("x", 1)).toThrow("Product x is not in the cart");
  });

  it("clear() empties the cart", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    cart.add(mkProduct("b", 2000), 2);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot() returns a deep copy", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0]!.product.id).toBe("a");
    // Mutating snapshot does not affect cart
    (snap[0] as { quantity: number }).quantity = 99;
    expect(cart.itemCount).toBe(2);
  });
});

describe("Cart.totals() pricing pipeline", () => {
  it("empty cart has all-zero totals", () => {
    const cart = new Cart();
    const t = cart.totals();
    expect(t).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("subtotal sums unitPriceCents × quantity", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
    cart.add(mkProduct("b", 500), 3);
    expect(cart.totals().subtotalCents).toBe(3500);
  });

  it("applies discount then tax on discounted subtotal", () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      taxCalculator: new RegionalTaxCalculator({ US: 0.10 }),
      region: "US",
    });
    cart.add(mkProduct("a", 10000), 1);
    const t = cart.totals();
    // subtotal 10000, discount 1000, discounted 9000, tax 900
    expect(t.subtotalCents).toBe(10000);
    expect(t.discountCents).toBe(1000);
    expect(t.taxCents).toBe(900);
    expect(t.totalCents).toBe(9000 + 900);
  });

  it("clamps discount to [0, subtotal]", () => {
    // FixedAmount(99999) on subtotal 1000 → clamped to 1000
    const cart = new Cart({
      discountPolicy: new FixedAmountDiscountPolicy(99999),
    });
    cart.add(mkProduct("a", 1000), 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(1000);
    expect(t.totalCents).toBe(0);
  });

  it("shipping uses discounted subtotal", () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(50),
      shippingCalculator: new FlatShippingCalculator(500, 6000),
    });
    cart.add(mkProduct("a", 10000), 1);
    // subtotal 10000, discount 5000, discounted 5000 < freeOver 6000 → 500 shipping
    const t = cart.totals();
    expect(t.shippingCents).toBe(500);
  });

  it("defaults: no discount, no tax, free shipping, region US", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(1000);
  });

  it("total = discountedSubtotal + tax + shipping", () => {
    const cart = new Cart({
      discountPolicy: new FixedAmountDiscountPolicy(200),
      taxCalculator: new RegionalTaxCalculator({ US: 0.08 }),
      shippingCalculator: new FlatShippingCalculator(599),
      region: "US",
    });
    cart.add(mkProduct("a", 5000), 1);
    const t = cart.totals();
    // subtotal 5000, discount 200, discounted 4800
    // tax 8% of 4800 = 384
    // shipping 599
    expect(t.totalCents).toBe(4800 + 384 + 599);
  });
});

describe("Cart.checkout()", () => {
  it("returns totals and lines for simple checkout", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.lines).toHaveLength(1);
  });

  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);

    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher: fetcher });
    expect(result.totals.subtotalCents).toBe(1500);
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("a");
  });

  it("throws InventoryError when available is false", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 5);

    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: false, reason: "discontinued" }),
    };
    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.unreachable("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const ie = e as InventoryError;
      expect(ie.productId).toBe("a");
      expect(ie.requested).toBe(5);
    }
  });

  it("throws InventoryError on partial-stock denial (availableQuantity < requested)", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 10);

    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.unreachable("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const ie = e as InventoryError;
      expect(ie.productId).toBe("a");
      expect(ie.requested).toBe(10);
      expect(ie.available).toBe(3);
    }
  });

  it("passes when inventory check is available with sufficient quantity", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);

    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 5,
      }),
    };
    const result = await cart.checkout({ inventoryChecker: checker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("uses asyncTaxProvider for tax calculation", async () => {
    const cart = new Cart({
      discountPolicy: new NoDiscountPolicy(),
      region: "US-CA",
    });
    cart.add(mkProduct("a", 10000), 1);

    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };
    const result = await cart.checkout({ asyncTaxProvider: provider });
    // tax = floor(10000 * 0.0875) = 875
    expect(result.totals.taxCents).toBe(875);
    expect(provider.getRate).toHaveBeenCalledWith("US-CA");
  });

  it("async tax works with discount + shipping composition", async () => {
    const cart = new Cart({
      discountPolicy: new FixedAmountDiscountPolicy(1000),
      shippingCalculator: new FlatShippingCalculator(500),
      region: "US",
    });
    cart.add(mkProduct("a", 10000), 1);

    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.10),
    };
    const result = await cart.checkout({ asyncTaxProvider: provider });
    // subtotal 10000, discount 1000, discounted 9000
    // tax = floor(9000 * 0.10) = 900
    // shipping 500
    expect(result.totals.discountCents).toBe(1000);
    expect(result.totals.taxCents).toBe(900);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(9000 + 900 + 500);
  });

  it("propagates asyncTaxProvider error", async () => {
    const cart = new Cart({ region: "US" });
    cart.add(mkProduct("a", 1000), 1);

    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider: provider })).rejects.toThrow(
      "tax service down",
    );
  });

  it("uses all collaborators together", async () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      shippingCalculator: new FlatShippingCalculator(300),
      region: "FR",
    });
    cart.add(mkProduct("a", 5000), 2);

    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(6000),
    };
    const checker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const taxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.20),
    };

    const result = await cart.checkout({
      priceFetcher: fetcher,
      inventoryChecker: checker,
      asyncTaxProvider: taxProvider,
    });

    // refreshed price: 6000 × 2 = 12000 subtotal
    // discount 10% of 12000 = 1200, discounted = 10800
    // tax 20% of 10800 = 2160
    // shipping 300
    expect(result.totals.subtotalCents).toBe(12000);
    expect(result.totals.discountCents).toBe(1200);
    expect(result.totals.taxCents).toBe(2160);
    expect(result.totals.shippingCents).toBe(300);
    expect(result.totals.totalCents).toBe(10800 + 2160 + 300);
  });

  it("inventory check uses first denial among multiple lines", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    cart.add(mkProduct("b", 2000), 5);

    const checker: InventoryChecker = {
      check: vi.fn()
        .mockResolvedValueOnce({ available: true })
        .mockResolvedValueOnce({ available: false, reason: "out of stock" }),
    };

    try {
      await cart.checkout({ inventoryChecker: checker });
      expect.unreachable("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      expect((e as InventoryError).productId).toBe("b");
    }
  });

  it("checkout without any collaborators uses sync pipeline", async () => {
    const cart = new Cart({
      taxCalculator: new RegionalTaxCalculator({ US: 0.05 }),
      region: "US",
    });
    cart.add(mkProduct("a", 2000), 1);
    const result = await cart.checkout();
    expect(result.totals.taxCents).toBe(100);
    expect(result.totals.totalCents).toBe(2100);
  });
});

