+    cart.add(mkProduct("a", 5000), 2);
+
+    const fetcher: PriceFetcher = {
+      fetchPriceCents: vi.fn().mockResolvedValue(6000),
+    };
+    const checker: InventoryChecker = {
+      check: vi.fn().mockResolvedValue({ available: true }),
+    };
+    const taxProvider: AsyncTaxRateProvider = {
+      getRate: vi.fn().mockResolvedValue(0.20),
+    };
+
+    const result = await cart.checkout({
+      priceFetcher: fetcher,
+      inventoryChecker: checker,
+      asyncTaxProvider: taxProvider,
+    });
+
+    // refreshed price: 6000 × 2 = 12000 subtotal
+    // discount 10% of 12000 = 1200, discounted = 10800
+    // tax 20% of 10800 = 2160
+    // shipping 300
+    expect(result.totals.subtotalCents).toBe(12000);
+    expect(result.totals.discountCents).toBe(1200);
+    expect(result.totals.taxCents).toBe(2160);
+    expect(result.totals.shippingCents).toBe(300);
+    expect(result.totals.totalCents).toBe(10800 + 2160 + 300);
+  });
+
+  it("inventory check uses first denial among multiple lines", async () => {
+    const cart = new Cart();
+    cart.add(mkProduct("a", 1000), 1);
+    cart.add(mkProduct("b", 2000), 5);
+
+    const checker: InventoryChecker = {
+      check: vi.fn()
+        .mockResolvedValueOnce({ available: true })
+        .mockResolvedValueOnce({ available: false, reason: "out of stock" }),
+    };
+
+    try {
+      await cart.checkout({ inventoryChecker: checker });
+      expect.unreachable("should have thrown");
+    } catch (e) {
+      expect(e).toBeInstanceOf(InventoryError);
+      expect((e as InventoryError).productId).toBe("b");
+    }
+  });
+
+  it("checkout without any collaborators uses sync pipeline", async () => {
+    const cart = new Cart({
+      taxCalculator: new RegionalTaxCalculator({ US: 0.05 }),
+      region: "US",
+    });
+    cart.add(mkProduct("a", 2000), 1);
+    const result = await cart.checkout();
+    expect(result.totals.taxCents).toBe(100);
+    expect(result.totals.totalCents).toBe(2100);
+  });
+});
